import{_ as a,o as t,c as i,a2 as n}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"Prefilled links","description":"Generate and use form links with values already filled in.","frontmatter":{"title":"Prefilled links","description":"Generate and use form links with values already filled in."},"headers":[],"relativePath":"en/formulare/vorausgefuellte-links.md","filePath":"en/formulare/vorausgefuellte-links.md","lastUpdated":1787319236000}'),o={name:"en/formulare/vorausgefuellte-links.md"};function l(r,e,s,d,h,c){return t(),i("div",null,[...e[0]||(e[0]=[n('<h1 id="prefilled-links" tabindex="-1">Prefilled links <a class="header-anchor" href="#prefilled-links" aria-label="Permalink to &quot;Prefilled links&quot;">​</a></h1><p>A <strong>prefilled link</strong> opens a form with certain fields already filled in. People filling it out need to enter less — and you learn more about the context.</p><h2 id="generating-a-link" tabindex="-1">Generating a link <a class="header-anchor" href="#generating-a-link" aria-label="Permalink to &quot;Generating a link&quot;">​</a></h2><p>In a form&#39;s share dialog: <strong>Share form prefilled</strong>.</p><p>An editor opens showing the form itself:</p><blockquote><p><em>Create a link to prefill this form.</em></p><p><em>Please enter the data in the corresponding form fields. Copy the generated link and use it to share the form with the prefilled data quickly and easily.</em></p></blockquote><p>So you simply fill out the form the way you want recipients to see it, and copy the generated link.</p><h2 id="typical-uses" tabindex="-1">Typical uses <a class="header-anchor" href="#typical-uses" aria-label="Permalink to &quot;Typical uses&quot;">​</a></h2><h3 id="tracking-the-source" tabindex="-1">Tracking the source <a class="header-anchor" href="#tracking-the-source" aria-label="Permalink to &quot;Tracking the source&quot;">​</a></h3><p>Create a <code>Source</code> field on the Grid, set it to <strong>Not visible</strong> in the form, and generate a link per channel with a different value — <code>Newsletter</code>, <code>Website</code>, <code>Trade show</code>.</p><p>People filling out the form notice nothing. Later, in a view grouped by <code>Source</code>, you can see which channel produced how much.</p><div class="tip custom-block"><p class="custom-block-title">The most common use case</p><p>This combination of a hidden field and a prefilled link is the standard way to distinguish between campaigns — without people filling out the form having to enter anything extra.</p></div><h3 id="prefilling-recurring-information" tabindex="-1">Prefilling recurring information <a class="header-anchor" href="#prefilling-recurring-information" aria-label="Permalink to &quot;Prefilling recurring information&quot;">​</a></h3><p>Location, department, event, contact person: anything that&#39;s the same for a group of people filling out the form. Also set the fields to <strong>Not editable</strong> if the value should be fixed.</p><h3 id="sending-it-from-a-flow" tabindex="-1">Sending it from a Flow <a class="header-anchor" href="#sending-it-from-a-flow" aria-label="Permalink to &quot;Sending it from a Flow&quot;">​</a></h3><p>The Flow step <strong>Prefilled form link</strong> generates a link that opens an <strong>existing</strong> entry for editing.</p><p>That&#39;s how you build feedback loops: the Flow sends an email with the link, the person adds to or corrects something, and the change lands directly in the existing entry — no duplicate entries.</p><p>→ <a href="/en/flows/aktionen">Actions</a></p><h3 id="starting-a-flow-with-fixed-values" tabindex="-1">Starting a Flow with fixed values <a class="header-anchor" href="#starting-a-flow-with-fixed-values" aria-label="Permalink to &quot;Starting a Flow with fixed values&quot;">​</a></h3><p>Combined with <strong>Auto-submit</strong>, you get a link that submits itself as soon as it&#39;s opened, starting a Flow. As a QR code on a sign, a single scan is enough.</p><div class="warning custom-block"><p class="custom-block-title">Auto-submit needs complete prefill data</p><p>If the form submits itself, no one gets the chance to fill in required fields. <strong>All</strong> needed values must be set via the link or via <em>Prefilled</em> — otherwise the submission fails.</p></div><h2 id="on-pages" tabindex="-1">On Pages <a class="header-anchor" href="#on-pages" aria-label="Permalink to &quot;On Pages&quot;">​</a></h2><p>Buttons on a <a href="/en/seiten/was-sind-seiten">Page</a> can also open a form prefilled. The dialog for this is called <em>Prefill form</em> — <em>Configure the button to prefill form data.</em></p><h2 id="limits-and-caution" tabindex="-1">Limits and caution <a class="header-anchor" href="#limits-and-caution" aria-label="Permalink to &quot;Limits and caution&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">Prefilled values sit in the link</p><p>The values are part of the address and therefore readable by anyone who has the link — even for fields set to <em>Not visible</em>.</p><p>Don&#39;t put personal or confidential data there. &quot;Not visible&quot; doesn&#39;t mean &quot;secret&quot;: it only hides the field in the interface, nothing more.</p></div><div class="warning custom-block"><p class="custom-block-title">Field deleted — link unusable</p><p>A prefilled link points to specific fields. If a field is deleted or its type changed, the prefill no longer works. Check links in circulation after structural changes.</p></div><div class="tip custom-block"><p class="custom-block-title">Name your links</p><p>Use <strong>Add link</strong> to create a separate, named link per channel. That way you can see in the <a href="/en/zusammenarbeit/externe-links">links overview</a> what each link is for, and disable individual ones as needed.</p></div><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><ul><li><a href="/en/formulare/formular-teilen">Sharing a form</a></li><li><a href="/en/formulare/felder-konfigurieren">Configuring fields</a></li><li><a href="/en/formulare/eintraege-bearbeiten">Editing entries via form</a></li></ul>',29)])])}const p=a(o,[["render",l]]);export{u as __pageData,p as default};
